import React, { useState } from 'react';
import './ToolCard.css';

export default function ToolCard({ tool, onOpenModal }) {
  const [expanded, setExpanded] = useState(false);

  return (
    <div className={`card${expanded ? ' expanded' : ''}`}>
      <div className="card-glow" />
      <div className="card-top">
        <div className="card-name-row">
          <span className="card-emoji">{tool.icon}</span>
          <span className="card-name">{tool.n}</span>
          <span className={`badge badge-${tool.t}`}>
            {tool.t === 'free' ? '✅ Free' : tool.t === 'paid' ? '💎 Paid' : '🔓 Free+'}
          </span>
        </div>
        <p className="card-desc">{tool.d}</p>
      </div>
      <div className="card-body">
        {expanded && tool.about && (
          <p className="card-detail">{tool.about}</p>
        )}
        {expanded && tool.steps && (
          <div className="card-steps">
            {tool.steps.slice(0, 3).map((s, i) => (
              <div className="step" key={i}>
                <div className="step-num">{i + 1}</div>
                <span className="step-text">{s}</span>
              </div>
            ))}
          </div>
        )}
        {expanded && tool.tips && (
          <div className="card-tags">
            {tool.tips.slice(0, 2).map((tip, i) => (
              <span className="tag" key={i}>💡 {tip.slice(0, 40)}…</span>
            ))}
          </div>
        )}
      </div>
      <div className="card-footer">
        <a className="card-link" href={tool.url} target="_blank" rel="noopener noreferrer">
          Visit Tool →
        </a>
        <button className="expand-btn" onClick={() => setExpanded(e => !e)}>
          {expanded ? 'Collapse' : 'Quick View'}
        </button>
        <button className="detail-btn" onClick={() => onOpenModal(tool)}>
          Full Details
        </button>
        {tool.yt && tool.yt[0] && (
          <a className="yt-link" href={tool.yt[0].url} target="_blank" rel="noopener noreferrer">
            ▶ Hindi
          </a>
        )}
      </div>
    </div>
  );
}
